"""Interface phrasebook for the seven supported languages.

Keys are the English wording; unknown text safely stays English.
"""
from __future__ import annotations

LANGUAGES = {
    "en": "English",
    "fr": "Français",
    "de": "Deutsch",
    "it": "Italiano",
    "ro": "Română",
    "pl": "Polski",
    "es": "Español",
}

AI_OUTPUT_LANGUAGES = {
    "en": "English",
    "fr": "French (français)",
    "de": "German (Deutsch)",
    "it": "Italian (italiano)",
    "ro": "Romanian (română)",
    "pl": "Polish (polski)",
    "es": "Spanish (español)",
}


def ai_output_language_instruction(language_code: str) -> str:
    """Tell the model explicitly to write all analysis in the selected UI language."""
    language = AI_OUTPUT_LANGUAGES.get(language_code, AI_OUTPUT_LANGUAGES["en"])
    return (
        f"LANGUAGE REQUIREMENT: Write every section of the complete answer in {language}. "
        "Translate the analysis even when source excerpts use another language. "
        "Only proper names, publication names, and cited source titles may remain in their original language. "
        "Do not switch or mix languages."
    )

