def _add(table: dict[str, tuple[str, str, str, str, str, str]]) -> None:
    """Register translations given in the order fr, de, it, ro, pl, es."""
    for text, values in table.items():
        UI[text] = dict(zip(("fr", "de", "it", "ro", "pl", "es"), values, strict=True))


